function volume(shape, d){
  switch(shape){
    case 'cube': return Math.pow(d.s,3);
    case 'sphere': return 4/3*Math.PI*d.r*d.r*d.r;
    case 'cylinder': return Math.PI*d.r*d.r*h_(d);
    case 'cone': return 1/3*Math.PI*d.r*d.r*h_(d);
    case 'prism': return d.l*d.w*h_(d);
    case 'pyramid': return 1/3*d.l*d.w*h_(d);
    default: return NaN;
  }
}
function surfaceArea(shape, d){
  switch(shape){
    case 'cube': return 6*d.s*d.s;
    case 'sphere': return 4*Math.PI*d.r*d.r;
    case 'cylinder': return 2*Math.PI*d.r*(d.r+h_(d));
    case 'cone': return Math.PI*d.r*(d.r+Math.sqrt(d.r*d.r+h_(d)*h_(d)));
    case 'prism': return 2*(d.l*d.w+d.l*h_(d)+d.w*h_(d));
    case 'pyramid': { var l=d.l,w=d.w,h=h_(d); return l*w + l*Math.sqrt((w/2)*(w/2)+h*h) + w*Math.sqrt((l/2)*(l/2)+h*h); }
    default: return NaN;
  }
}
// helper: pull height from d.h or d.height
function h_(d){ return d.h!==undefined?d.h:(d.height!==undefined?d.height:0); }
var EXPORTS = { volume:volume, surfaceArea:surfaceArea };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.VolumeForgePure = EXPORTS; }
